// Get all incoming items
const items = $input.all();

// Convert n8n items into plain JSON objects
const input = items.map(item => item.json);

// ------------------------------------------------------------
// Validation
// ------------------------------------------------------------

if (input.length < 2) {
	throw new Error(
		`Expected at least 2 input objects. Received ${input.length}.`
	);
}

const master = input[0];

if (!master.haveLatex || !Array.isArray(master.haveLatex)) {
	throw new Error(
		"The first item must contain a haveLatex[] array."
	);
}

const questions = master.haveLatex;
const conversions = input.slice(1);

if (questions.length !== conversions.length) {
	throw new Error(
		`Question count (${questions.length}) does not match conversion count (${conversions.length}).`
	);
}

// ------------------------------------------------------------
// Remove xmlns from all MathML
// ------------------------------------------------------------

function cleanMathML(mathml) {

	if (typeof mathml !== "string") {
		return mathml;
	}

	return mathml
		.replace(/\s+xmlns="http:\/\/www\.w3\.org\/1998\/Math\/MathML"/g, "")
		.trim();
}

conversions.forEach((conversion, index) => {

	if (!conversion.success) {
		throw new Error(`Conversion ${index + 1} failed.`);
	}

	if (!Array.isArray(conversion.data)) {
		throw new Error(
			`Conversion ${index + 1} does not contain data[].`
		);
	}

	conversion.data.forEach(item => {

		if (typeof item.mathml === "string") {
			item.mathml = cleanMathML(item.mathml);
		}

	});
});

// ------------------------------------------------------------
// Inject MathML recursively
// ------------------------------------------------------------

function injectMathML(value, latexMap) {

	if (typeof value === "string") {

		return value.replace(/\{\{latex\[(\d+)\]\}\}/g, (_, index) => {

			index = Number(index);

			if (!latexMap[index]) {
				throw new Error(
					`Missing latex index ${index}`
				);
			}

			return latexMap[index].mathml;
		});
	}

	if (Array.isArray(value)) {
		return value.map(v => injectMathML(v, latexMap));
	}

	if (value && typeof value === "object") {

		Object.keys(value).forEach(key => {
			value[key] = injectMathML(value[key], latexMap);
		});

		return value;
	}

	return value;
}

// ------------------------------------------------------------
// Merge
// ------------------------------------------------------------

questions.forEach((question, questionIndex) => {

	const conversion = conversions[questionIndex];

	if (!Array.isArray(question.latex)) {
		throw new Error(
			`Question ${questionIndex + 1} does not contain latex[].`
		);
	}

	if (question.latex.length !== conversion.data.length) {
		throw new Error(
			[
				`Latex length mismatch`,
				`Question ${questionIndex + 1}`,
				`Question Latex Count : ${question.latex.length}`,
				`MathML Count : ${conversion.data.length}`
			].join("\n")
		);
	}

	const mergedLatex = question.latex.map((latexString, latexIndex) => {

		const converted = conversion.data[latexIndex];

		if (!converted) {
			throw new Error(
				`Missing MathML for Question ${questionIndex + 1}, Latex ${latexIndex}`
			);
		}

		if (latexString !== converted.latex) {
			throw new Error(
				[
					`Latex mismatch`,
					`Question : ${questionIndex + 1}`,
					`Latex Index : ${latexIndex}`,
					`Expected : ${latexString}`,
					`Received : ${converted.latex}`
				].join("\n")
			);
		}

		return {
			latex: converted.latex,
			mathml: converted.mathml
		};

	});

	// Replace placeholders recursively
	injectMathML(question, mergedLatex);

	// Replace latex array with merged objects
	question.latex = mergedLatex;

});

// ------------------------------------------------------------
// Return in the same structure as input
// ------------------------------------------------------------

return [
	{
		json: {
			haveLatex: questions
		}
	}
];

function validateLatex(questionObj) {
	const errors = [];
	const warnings = [];

	const latex = Array.isArray(questionObj.latex)
		? questionObj.latex
		: [];

	const fields = [
		{
			path: "question",
			value: questionObj.question || "",
		},
		{
			path: "explanation",
			value: questionObj.explanation || "",
		},
		{
			path: "hint",
			value: questionObj.hint || "",
		},
		...(questionObj.options || []).map((option, index) => ({
			path: `options[${index}].name`,
			value: option?.name || "",
		})),
	];

	const validPlaceholderRegex = /{{\s*latex\[(\d+)\]\s*}}/gi;
	const latexKeywordRegex = /\blatex\b/i;

	let hasLatexReference = false;
	const usedIndexes = new Set();

	fields.forEach(({ path, value }) => {
		if (!value) return;

		let match;
		validPlaceholderRegex.lastIndex = 0;

		while ((match = validPlaceholderRegex.exec(value)) !== null) {
			hasLatexReference = true;

			const index = Number(match[1]);
			usedIndexes.add(index);

			if (index >= latex.length) {
				errors.push(
					`${path} contains invalid latex reference {{latex[${index}]}} but latex array length is ${latex.length}.`
				);
			}
		}

		if (
			latexKeywordRegex.test(value) &&
			!/{{\s*latex\[\d+\]\s*}}/i.test(value)
		) {
			warnings.push(
				`${path} contains the word 'latex' but no valid placeholder format '{{latex[index]}}' was found.`
			);
		}
	});

	// Case 1
	if (hasLatexReference && latex.length === 0) {
		errors.push(
			"Latex placeholders are used in content, but latex array is empty."
		);
	}

	// Case 2
	if (latex.length > 0 && !hasLatexReference) {
		warnings.push(
			`Latex array contains ${latex.length} entries but no latex placeholders are used anywhere.`
		);
	}

	// Case 3
	if (latex.length > 0) {
		const unusedIndexes = [];

		for (let i = 0; i < latex.length; i++) {
			if (!usedIndexes.has(i)) {
				unusedIndexes.push(i);
			}
		}

		if (unusedIndexes.length) {
			warnings.push(
				`Unused latex entries found at indexes: ${unusedIndexes.join(", ")}.`
			);
		}
	}

	// Case 4
	latex.forEach((item, index) => {
		if (
			item === null ||
			item === undefined ||
			String(item).trim() === ""
		) {
			errors.push(`latex[${index}] is empty.`);
		}
	});

	// Case 5
	const seen = new Map();

	latex.forEach((item, index) => {
		const value = String(item).trim();

		if (!value) return;

		if (seen.has(value)) {
			warnings.push(
				`Duplicate latex content found at indexes ${seen.get(value)} and ${index}.`
			);
		} else {
			seen.set(value, index);
		}
	});

	return {
		valid: errors.length === 0,
		errors,
		warnings,
